/* Runtime contract of code generated by pc/tools/lift.py (x86-32 guest -> C).

   Guest memory is one flat 32-bit space starting at X86_MEM_BASE. On a 32-bit x86 host
   (the differential test harness) the base is 0 and guest addresses are host addresses;
   on ARM64 it is a reserved 4 GB region. x86 and ARM64 are both little-endian, so loads and
   stores need no byte swapping. */
#ifndef X86RT_H
#define X86RT_H

#include <stdint.h>
#include <setjmp.h>
#include <string.h>

#ifndef X86_MEM_BASE
extern uintptr_t x86_mem_base;
#define X86_MEM_BASE x86_mem_base
#endif

typedef union X86Xmm {
    float f[4];
    uint32_t u[4];
    int32_t i[4];
    double d[2];
    uint64_t q[2];
} X86Xmm;

typedef struct X86Ctx {
    uint32_t eax, ecx, edx, ebx, esp, ebp, esi, edi;
    uint32_t fs_base; /* guest address of the TEB */
    /* x87: values held as double (see x87_round), physical registers st[], top of stack,
       bit mask of non-empty physical registers, control word, status word (C0..C3). */
    double st[8];
    uint32_t ftop, ftag;
    uint32_t fcw, fsw;
    X86Xmm xmm[8];
    uint32_t mxcsr;
    uint64_t mm[8]; /* MMX, kept apart from the x87 registers (the game does not mix them) */
} X86Ctx;

typedef void (*X86Fn)(X86Ctx *);

/* Registers live in C locals inside a lifted function and go through ctx around calls. */
#define X86_LOCALS uint32_t eax = ctx->eax, ecx = ctx->ecx, edx = ctx->edx, ebx = ctx->ebx, \
                        esp = ctx->esp, ebp = ctx->ebp, esi = ctx->esi, edi = ctx->edi
#define X86_SPILL (ctx->eax = eax, ctx->ecx = ecx, ctx->edx = edx, ctx->ebx = ebx, \
                   ctx->esp = esp, ctx->ebp = ebp, ctx->esi = esi, ctx->edi = edi)
#define X86_RELOAD (eax = ctx->eax, ecx = ctx->ecx, edx = ctx->edx, ebx = ctx->ebx, \
                    esp = ctx->esp, ebp = ctx->ebp, esi = ctx->esi, edi = ctx->edi)

#define X86_PTR(a) ((uintptr_t)X86_MEM_BASE + (uint32_t)(a))
static inline uint8_t ld8(uint32_t a) { uint8_t v; memcpy(&v, (void *)X86_PTR(a), 1); return v; }
static inline uint16_t ld16(uint32_t a) { uint16_t v; memcpy(&v, (void *)X86_PTR(a), 2); return v; }
static inline uint32_t ld32(uint32_t a) { uint32_t v; memcpy(&v, (void *)X86_PTR(a), 4); return v; }
static inline uint64_t ld64(uint32_t a) { uint64_t v; memcpy(&v, (void *)X86_PTR(a), 8); return v; }
static inline void st8(uint32_t a, uint8_t v) { memcpy((void *)X86_PTR(a), &v, 1); }
static inline void st16(uint32_t a, uint16_t v) { memcpy((void *)X86_PTR(a), &v, 2); }
static inline void st32(uint32_t a, uint32_t v) { memcpy((void *)X86_PTR(a), &v, 4); }
static inline void st64(uint32_t a, uint64_t v) { memcpy((void *)X86_PTR(a), &v, 8); }
static inline float ldf(uint32_t a) { float v; memcpy(&v, (void *)X86_PTR(a), 4); return v; }
static inline double ldd(uint32_t a) { double v; memcpy(&v, (void *)X86_PTR(a), 8); return v; }
static inline void stf(uint32_t a, float v) { memcpy((void *)X86_PTR(a), &v, 4); }
static inline void std_(uint32_t a, double v) { memcpy((void *)X86_PTR(a), &v, 8); }
static inline X86Xmm ldx(uint32_t a) { X86Xmm v; memcpy(&v, (void *)X86_PTR(a), 16); return v; }
static inline void stx(uint32_t a, X86Xmm v) { memcpy((void *)X86_PTR(a), &v, 16); }
static inline uint32_t f2u(float f) { uint32_t u; memcpy(&u, &f, 4); return u; }
static inline float u2f(uint32_t u) { float f; memcpy(&f, &u, 4); return f; }

/* --- x87 --- */
#define ST(i) (ctx->st[(ctx->ftop + (i)) & 7])

static inline void x87_push(X86Ctx *c, double v)
{
    c->ftop = (c->ftop - 1) & 7;
    c->st[c->ftop] = v;
    c->ftag |= 1u << c->ftop;
}

/* "Real indefinite": what a masked stack underflow reads from an empty register. Empty registers
   hold it, so reading one (fstp after an fsincos that did not push, say) behaves like the x87. */
static inline double x87_indefinite(void)
{
    uint64_t u = 0xFFF8000000000000ull;
    double v;
    memcpy(&v, &u, 8);
    return v;
}

/* fxam: class of st(0) in C3 C2 C0, sign in C1. Values are kept as double, and every nonzero
   finite double is a normal number in the x87's extended format. */
static inline void x87_examine(X86Ctx *c)
{
    double v = c->st[c->ftop];
    uint32_t cc;
    if (!((c->ftag >> c->ftop) & 1)) cc = 0x4100u;          /* empty: C3, C0 */
    else if (__builtin_isnan(v)) cc = 0x0100u;               /* NaN: C0 */
    else if (__builtin_isinf(v)) cc = 0x0500u;               /* infinity: C2, C0 */
    else if (v == 0.0) cc = 0x4000u;                         /* zero: C3 */
    else cc = 0x0400u;                                       /* normal: C2 */
    if (__builtin_signbit(v)) cc |= 0x0200u;                 /* C1: sign */
    c->fsw = (c->fsw & ~0x4700u) | cc;
}

static inline void x87_pop(X86Ctx *c)
{
    c->ftag &= ~(1u << c->ftop);
    c->st[c->ftop] = x87_indefinite();
    c->ftop = (c->ftop + 1) & 7;
}

/* Initial x87 state of a context: empty stack, control word as after finit. */
static inline void x87_init(X86Ctx *c)
{
    for (int i = 0; i < 8; i++) c->st[i] = x87_indefinite();
    c->ftop = 0;
    c->ftag = 0;
    c->fcw = 0x37F;
    c->fsw = 0;
}

/* Precision control: 24-bit (Direct3D 9 sets it unless FPU_PRESERVE) rounds the significand of
   every result to 24 bits but keeps the wide exponent, so it is not a cast to float (that would
   flush small and overflow large values). Rounds to nearest-even in the bits of the double.
   53- and 64-bit keep double (64-bit extended precision is not modelled). */
static inline double x87_round24(double v)
{
    uint64_t u;
    memcpy(&u, &v, 8);
    if (((u >> 52) & 0x7FF) == 0x7FF || ((u >> 52) & 0x7FF) == 0)
        return v; /* inf, NaN, zero and doubles below the normal range are left as they are */
    uint64_t low = u & ((1ull << 29) - 1), half = 1ull << 28;
    u &= ~((1ull << 29) - 1);
    if (low > half || (low == half && (u & (1ull << 29))))
        u += 1ull << 29; /* a carry into the exponent is the correct rounding */
    memcpy(&v, &u, 8);
    return v;
}

static inline double x87_round(const X86Ctx *c, double v)
{
    return ((c->fcw >> 8) & 3) == 0 ? x87_round24(v) : v;
}

/* Rounding control for fist/frndint: nearest-even, down, up, toward zero. */
static inline double x87_rc(const X86Ctx *c, double v)
{
    switch ((c->fcw >> 10) & 3) {
    case 0: return __builtin_rint(v);
    case 1: return __builtin_floor(v);
    case 2: return __builtin_ceil(v);
    default: return __builtin_trunc(v);
    }
}

static inline int64_t x87_fist(const X86Ctx *c, double v, int bits)
{
    double r = x87_rc(c, v);
    double lim = bits == 16 ? 32768.0 : bits == 32 ? 2147483648.0 : 9223372036854775808.0;
    if (!(r >= -lim && r < lim)) /* NaN or out of range: integer indefinite */
        return bits == 16 ? (int64_t)(int16_t)0x8000 : bits == 32 ? (int64_t)(int32_t)0x80000000u : INT64_MIN;
    return (int64_t)r;
}

/* fsin (0), fcos (1), fsincos (2), fptan (3). For |x| >= 2^63 the x87 sets C2 and leaves the
   stack unchanged; otherwise C2 is cleared. Precision control does not apply to these. Results
   come from libm, which can differ from the x87 microcode in the last bit. */
static inline void x87_trig(X86Ctx *c, int op)
{
    double x = c->st[c->ftop & 7];
    if (__builtin_fabs(x) >= 9223372036854775808.0 && x == x && __builtin_fabs(x) != __builtin_inf()) {
        c->fsw |= 0x0400u;
        return;
    }
    c->fsw &= ~0x0400u;
    double s = __builtin_sin(x), k = __builtin_cos(x);
    switch (op) {
    case 0: c->st[c->ftop & 7] = s; break;
    case 1: c->st[c->ftop & 7] = k; break;
    case 2: c->st[c->ftop & 7] = s; x87_push(c, k); break;
    default: c->st[c->ftop & 7] = __builtin_tan(x); x87_push(c, 1.0); break;
    }
}

/* fcom/fucom: C3 C2 C0 = 000 greater, 001 less, 100 equal, 111 unordered. */
static inline void x87_compare(X86Ctx *c, double a, double b)
{
    uint32_t cc = (a != a || b != b) ? 0x4500u : a < b ? 0x0100u : a == b ? 0x4000u : 0u;
    c->fsw = (c->fsw & ~0x4700u) | cc;
}

static inline uint32_t x87_status(const X86Ctx *c) { return (c->fsw & ~0x3800u) | ((c->ftop & 7) << 11); }

/* 80-bit extended <-> double (fld/fstp tbyte). */
static inline double x87_ld80(uint32_t a)
{
    uint64_t m = ld64(a);
    uint16_t se = ld16(a + 8);
    int e = se & 0x7FFF;
    double v;
    if (e == 0 && m == 0) v = 0.0;
    else if (e == 0x7FFF) v = (m << 1) ? __builtin_nan("") : __builtin_inf();
    else v = __builtin_ldexp((double)m, e - 16383 - 63);
    return (se & 0x8000) ? -v : v;
}

static inline void x87_st80(uint32_t a, double v)
{
    uint64_t bits;
    memcpy(&bits, &v, 8);
    uint16_t sign = (uint16_t)((bits >> 48) & 0x8000);
    int e = (int)((bits >> 52) & 0x7FF);
    uint64_t frac = bits & 0xFFFFFFFFFFFFFull, m;
    int e80;
    if (e == 0 && frac == 0) { m = 0; e80 = 0; }
    else if (e == 0x7FF) { m = 0x8000000000000000ull | (frac << 11); e80 = 0x7FFF; }
    else if (e == 0) { int s = __builtin_clzll(frac) - 11; m = (frac << (11 + s)); e80 = 1 - 1023 - s + 16383; }
    else { m = 0x8000000000000000ull | (frac << 11); e80 = e - 1023 + 16383; }
    st64(a, m);
    st16(a + 8, (uint16_t)(sign | e80));
}

/* --- SSE --- */
/* cvtss2si/cvttss2si: out of range or NaN gives the integer indefinite 0x80000000. */
static inline uint32_t sse_cvt(double r, int trunc, uint32_t mxcsr)
{
    if (trunc) r = __builtin_trunc(r);
    else switch ((mxcsr >> 13) & 3) {
        case 0: r = __builtin_rint(r); break;
        case 1: r = __builtin_floor(r); break;
        case 2: r = __builtin_ceil(r); break;
        default: r = __builtin_trunc(r); break;
    }
    if (!(r >= -2147483648.0 && r < 2147483648.0)) return 0x80000000u;
    return (uint32_t)(int32_t)r;
}

/* --- MMX (only the few forms this exe uses) --- */
static inline uint64_t mmx_pxor(uint64_t a, uint64_t b) { return a ^ b; }
static inline uint64_t mmx_pand(uint64_t a, uint64_t b) { return a & b; }
/* 16-bit lanes */
#define MMX_W(v, i) ((uint16_t)((v) >> (16 * (i))))
#define MMX_PACKW(e0, e1, e2, e3) ((uint64_t)(uint16_t)(e0) | ((uint64_t)(uint16_t)(e1) << 16) | \
                                   ((uint64_t)(uint16_t)(e2) << 32) | ((uint64_t)(uint16_t)(e3) << 48))
static inline int32_t mmx_ssat16(int32_t v) { return v < -32768 ? -32768 : v > 32767 ? 32767 : v; }
static inline uint64_t mmx_paddw(uint64_t a, uint64_t b)
{
    return MMX_PACKW(MMX_W(a, 0) + MMX_W(b, 0), MMX_W(a, 1) + MMX_W(b, 1), MMX_W(a, 2) + MMX_W(b, 2), MMX_W(a, 3) + MMX_W(b, 3));
}
static inline uint64_t mmx_psubw(uint64_t a, uint64_t b)
{
    return MMX_PACKW(MMX_W(a, 0) - MMX_W(b, 0), MMX_W(a, 1) - MMX_W(b, 1), MMX_W(a, 2) - MMX_W(b, 2), MMX_W(a, 3) - MMX_W(b, 3));
}
static inline uint64_t mmx_paddsw(uint64_t a, uint64_t b)
{
    int32_t r[4];
    for (int i = 0; i < 4; i++) r[i] = mmx_ssat16((int16_t)MMX_W(a, i) + (int16_t)MMX_W(b, i));
    return MMX_PACKW(r[0], r[1], r[2], r[3]);
}
static inline uint64_t mmx_psubusw(uint64_t a, uint64_t b)
{
    int32_t r[4];
    for (int i = 0; i < 4; i++) { int32_t v = (int32_t)MMX_W(a, i) - (int32_t)MMX_W(b, i); r[i] = v < 0 ? 0 : v; }
    return MMX_PACKW(r[0], r[1], r[2], r[3]);
}
static inline uint64_t mmx_pmulhw(uint64_t a, uint64_t b)
{
    int32_t r[4];
    for (int i = 0; i < 4; i++) r[i] = ((int32_t)(int16_t)MMX_W(a, i) * (int32_t)(int16_t)MMX_W(b, i)) >> 16;
    return MMX_PACKW(r[0], r[1], r[2], r[3]);
}
static inline uint64_t mmx_punpckhbw(uint64_t a, uint64_t b)
{
    uint64_t r = 0;
    for (int i = 0; i < 4; i++)
        r |= ((a >> (8 * (i + 4))) & 0xFF) << (16 * i) | ((b >> (8 * (i + 4))) & 0xFF) << (16 * i + 8);
    return r;
}
static inline uint64_t mmx_punpckhdq(uint64_t a, uint64_t b) { return (a >> 32) | (b & 0xFFFFFFFF00000000ull); }
static inline uint64_t mmx_psllw(uint64_t a, uint64_t n)
{
    if (n > 15) return 0;
    return MMX_PACKW(MMX_W(a, 0) << n, MMX_W(a, 1) << n, MMX_W(a, 2) << n, MMX_W(a, 3) << n);
}
static inline uint64_t mmx_psrlw(uint64_t a, uint64_t n)
{
    if (n > 15) return 0;
    return MMX_PACKW(MMX_W(a, 0) >> n, MMX_W(a, 1) >> n, MMX_W(a, 2) >> n, MMX_W(a, 3) >> n);
}
static inline uint64_t mmx_pslld(uint64_t a, uint64_t n)
{
    if (n > 31) return 0;
    return (uint64_t)((uint32_t)a << n) | ((uint64_t)((uint32_t)(a >> 32) << n) << 32);
}
static inline uint64_t mmx_psllq(uint64_t a, uint64_t n) { return n > 63 ? 0 : a << n; }
static inline uint64_t mmx_psrlq(uint64_t a, uint64_t n) { return n > 63 ? 0 : a >> n; }
static inline uint64_t mmx_por(uint64_t a, uint64_t b) { return a | b; }
static inline uint64_t mmx_paddd(uint64_t a, uint64_t b)
{
    return (uint64_t)(uint32_t)((uint32_t)a + (uint32_t)b) | ((uint64_t)(uint32_t)((uint32_t)(a >> 32) + (uint32_t)(b >> 32)) << 32);
}
static inline uint64_t mmx_punpckldq(uint64_t a, uint64_t b) { return (uint64_t)(uint32_t)a | ((uint64_t)(uint32_t)b << 32); }
/* Shifts of both dwords; counts above 31 give 0 (logical) or the sign (arithmetic). */
static inline uint64_t mmx_psrld(uint64_t a, uint64_t n)
{
    if (n > 31) return 0;
    return (uint64_t)((uint32_t)a >> n) | ((uint64_t)((uint32_t)(a >> 32) >> n) << 32);
}
static inline uint64_t mmx_psrad(uint64_t a, uint64_t n)
{
    if (n > 31) n = 31;
    return (uint64_t)(uint32_t)((int32_t)(uint32_t)a >> n) | ((uint64_t)(uint32_t)((int32_t)(uint32_t)(a >> 32) >> n) << 32);
}
static inline uint64_t mmx_punpcklbw(uint64_t a, uint64_t b)
{
    uint64_t r = 0;
    for (int k = 0; k < 4; k++)
        r |= ((a >> (8 * k)) & 0xFF) << (16 * k) | ((b >> (8 * k)) & 0xFF) << (16 * k + 8);
    return r;
}
static inline uint64_t mmx_punpcklwd(uint64_t a, uint64_t b)
{
    return (a & 0xFFFF) | (b & 0xFFFF) << 16 | ((a >> 16) & 0xFFFF) << 32 | ((b >> 16) & 0xFFFF) << 48;
}
static inline uint64_t mmx_punpckhwd(uint64_t a, uint64_t b) { return mmx_punpcklwd(a >> 32, b >> 32); }
static inline uint16_t mmx_sat16(int32_t v) { return (uint16_t)(v > 32767 ? 32767 : v < -32768 ? -32768 : v); }
static inline uint8_t mmx_satu8(int16_t v) { return (uint8_t)(v > 255 ? 255 : v < 0 ? 0 : v); }
static inline uint64_t mmx_packssdw(uint64_t a, uint64_t b)
{
    return (uint64_t)mmx_sat16((int32_t)a) | (uint64_t)mmx_sat16((int32_t)(a >> 32)) << 16 |
           (uint64_t)mmx_sat16((int32_t)b) << 32 | (uint64_t)mmx_sat16((int32_t)(b >> 32)) << 48;
}
static inline uint64_t mmx_packuswb(uint64_t a, uint64_t b)
{
    uint64_t r = 0;
    for (int k = 0; k < 4; k++) {
        r |= (uint64_t)mmx_satu8((int16_t)(a >> (16 * k))) << (8 * k);
        r |= (uint64_t)mmx_satu8((int16_t)(b >> (16 * k))) << (8 * k + 32);
    }
    return r;
}

/* x86 min/max: the second operand is returned when either is NaN or both are zero. */
static inline float sse_min(float a, float b) { return a < b ? a : b; }
static inline float sse_max(float a, float b) { return a > b ? a : b; }

/* Services the generated code calls; provided by the runtime (or the test harness). */
void x86_dispatch(X86Ctx *ctx, uint32_t target);      /* indirect call/jmp: guest address -> lifted fn */
void x86_trap(X86Ctx *ctx, uint32_t addr, const char *why) __attribute__((noreturn));
/* cpuid: the runtime reports the processor the guest sees (leaf in *eax, subleaf in *ecx). */
void x86_cpuid(X86Ctx *ctx, uint32_t *eax, uint32_t *ebx, uint32_t *ecx, uint32_t *edx);
/* rdtsc: a monotonic counter (the runtime's clock, in nanoseconds). */
uint64_t x86_rdtsc(X86Ctx *ctx);
/* lock prefix: the instruction runs under one runtime-wide lock. */
void x86_lock_enter(void);
void x86_lock_leave(void);

/* EH resume points. A function with catch/__except continuations (tools/eh.py) registers its
   host frame on entry; when the guest EH runtime jumps to one of them (an indirect jump to a
   non-entry), the runtime longjmps back into this frame with the guest's new ebp/esp in ctx.
   Every return of such a function pops the record. */
typedef struct X86Resume {
    jmp_buf jb;                   /* setjmp: __builtin_setjmp does not restore the frame on Win64 clang */
    struct X86Resume *prev;
    const uint32_t *targets;
    uint32_t ntargets, entry_esp, target;
} X86Resume;
void x86_resume_push(X86Ctx *ctx, X86Resume *r, const uint32_t *targets, uint32_t n);
void x86_resume_pop(X86Ctx *ctx, X86Resume *r);

/* Lazy flags. Every flag-setting instruction stores its kind, operands and result; a condition
   is computed only where it is read. The kind is a constant in the generated code, so the
   compiler folds x86_cc() to the one comparison actually needed and drops dead flag stores. */
enum { FL_ADD, FL_SUB, FL_LOGIC, FL_INC, FL_DEC, FL_NEG, FL_EXPL, FL_ADC, FL_SBB };
enum { CC_O, CC_NO, CC_B, CC_AE, CC_E, CC_NE, CC_BE, CC_A, CC_S, CC_NS, CC_P, CC_NP, CC_L, CC_GE, CC_LE, CC_G };

typedef struct X86Flags {
    int op;        /* FL_* */
    int bits;      /* 8, 16 or 32 */
    uint32_t a, b; /* operands (for ADC/SBB, b already excludes the carry-in) */
    uint32_t r;    /* result, masked to bits */
    uint32_t cin;  /* carry-in for ADC/SBB */
    int cf, of;    /* explicit CF/OF for FL_EXPL, and saved CF for INC/DEC */
    int zf, sf, pf; /* explicit for FL_EXPL only */
    int df;         /* direction flag (std/cld); 0 at every call boundary, as the ABI requires */
} X86Flags;

static inline uint32_t x86_mask(int bits) { return bits == 32 ? 0xFFFFFFFFu : ((1u << bits) - 1); }
static inline uint32_t x86_sign(int bits) { return 1u << (bits - 1); }

static inline int x86_cf(const X86Flags *f)
{
    uint32_t m = x86_mask(f->bits);
    switch (f->op) {
    case FL_ADD: return (f->r & m) < (f->a & m);
    case FL_SUB: return (f->a & m) < (f->b & m);
    case FL_ADC: return ((uint64_t)(f->a & m) + (f->b & m) + f->cin) > m;
    case FL_SBB: return (uint64_t)(f->a & m) < (uint64_t)(f->b & m) + f->cin;
    case FL_NEG: return (f->r & m) != 0;
    case FL_LOGIC: return 0;
    default: return f->cf; /* INC, DEC, EXPL */
    }
}

static inline int x86_of(const X86Flags *f)
{
    uint32_t s = x86_sign(f->bits);
    switch (f->op) {
    case FL_ADD: case FL_ADC: return ((~(f->a ^ f->b)) & (f->a ^ f->r) & s) != 0;
    case FL_SUB: case FL_SBB: return ((f->a ^ f->b) & (f->a ^ f->r) & s) != 0;
    case FL_INC: return (f->r & x86_mask(f->bits)) == s;
    case FL_DEC: return (f->r & x86_mask(f->bits)) == s - 1;
    case FL_NEG: return (f->r & x86_mask(f->bits)) == s;
    case FL_LOGIC: return 0;
    default: return f->of;
    }
}

static inline int x86_zf(const X86Flags *f) { return f->op == FL_EXPL ? f->zf : (f->r & x86_mask(f->bits)) == 0; }
static inline int x86_sf(const X86Flags *f) { return f->op == FL_EXPL ? f->sf : (f->r & x86_sign(f->bits)) != 0; }
static inline int x86_pf(const X86Flags *f) { return f->op == FL_EXPL ? f->pf : !__builtin_parity(f->r & 0xFF); }

/* Explicit flags from a result whose CF/OF are known (shifts, multiplies, bit scans). */
static inline void x86_expl(X86Flags *f, int bits, uint32_t r, int cf, int of)
{
    uint32_t m = x86_mask(bits);
    f->op = FL_EXPL; f->bits = bits; f->r = r & m; f->cf = cf; f->of = of;
    f->zf = (r & m) == 0; f->sf = (r & x86_sign(bits)) != 0; f->pf = !__builtin_parity(r & 0xFF);
}

static inline int x86_cc(const X86Flags *f, int cc)
{
    switch (cc) {
    case CC_O: return x86_of(f);
    case CC_NO: return !x86_of(f);
    case CC_B: return x86_cf(f);
    case CC_AE: return !x86_cf(f);
    case CC_E: return x86_zf(f);
    case CC_NE: return !x86_zf(f);
    case CC_BE: return x86_cf(f) || x86_zf(f);
    case CC_A: return !x86_cf(f) && !x86_zf(f);
    case CC_S: return x86_sf(f);
    case CC_NS: return !x86_sf(f);
    case CC_P: return x86_pf(f);
    case CC_NP: return !x86_pf(f);
    case CC_L: return x86_sf(f) != x86_of(f);
    case CC_GE: return x86_sf(f) == x86_of(f);
    case CC_LE: return x86_zf(f) || x86_sf(f) != x86_of(f);
    default: return !x86_zf(f) && x86_sf(f) == x86_of(f); /* CC_G */
    }
}

/* EFLAGS image (CF PF ZF SF OF; bit 1 always set) for lahf/pushfd. AF is not modelled. */
static inline uint32_t x86_eflags(const X86Flags *f)
{
    return 0x2u | (uint32_t)x86_cf(f) | ((uint32_t)x86_pf(f) << 2) | ((uint32_t)x86_zf(f) << 6) |
           ((uint32_t)x86_sf(f) << 7) | ((uint32_t)x86_of(f) << 11);
}

/* Load flags from an EFLAGS image (sahf: low byte only; popfd: also OF). */
static inline void x86_set_eflags(X86Flags *f, uint32_t e, int with_of)
{
    int of = with_of ? (int)((e >> 11) & 1) : x86_of(f);
    f->op = FL_EXPL; f->bits = 32; f->r = 0;
    f->cf = e & 1; f->pf = (e >> 2) & 1; f->zf = (e >> 6) & 1; f->sf = (e >> 7) & 1; f->of = of;
}

#endif
